def n_esimo_mayor(lista, n):
    if n <= 0:
        return None
    seen = set()
    contador = 0
    for num in lista:
        if num not in seen:
            seen.add(num)
            contador += 1
            if contador == n:
                return num
    return None

def formatear_bytes(n):
    if n == 0:
        return '0 B'

    unidades = ['B', 'KB', 'MB', 'GB']
    factor = 1024

    for i in range(4):
        if n < factor:
            return f'{n} {unidades[i]}'
        n //= factor
    return f'{n:.1f} {unidades[3]}'

def en_lotes(lista, tamano):
    if not lista:
        return []
    return [lista[i:i+tamano] for i in range(0, len(lista), tamano)]
